import{_ as t,o,c as d,a3 as n}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Setting up documents","description":"Personal documents and company documents in the app – with search, categories, deadlines and acknowledgement, optionally signed or assigned per person.","frontmatter":{"title":"Setting up documents","description":"Personal documents and company documents in the app – with search, categories, deadlines and acknowledgement, optionally signed or assigned per person."},"headers":[],"relativePath":"en/apptiveteams/dokumente.md","filePath":"en/apptiveteams/dokumente.md","lastUpdated":1789044113000}'),a={name:"en/apptiveteams/dokumente.md"};function i(r,e,s,h,c,l){return o(),d("div",null,[...e[0]||(e[0]=[n(`<h1 id="setting-up-documents" tabindex="-1">Setting up documents <a class="header-anchor" href="#setting-up-documents" aria-label="Permalink to &quot;Setting up documents&quot;">​</a></h1><p>A tab of type <code>Documents</code> shows documents from a Grid in the app: PDFs and other files with title, category, version and validity, plus a search and a filter by category. Documents that require an <strong>acknowledgement</strong> carry a deadline; the person confirms in the app, optionally with a signature, and you see in the Grid who confirmed when. If you need to be sure that <strong>everyone</strong> has read it, create the acknowledgements per person up front – by hand or with a flow – then the Grid also shows who has not yet.</p><p>A tab always shows <strong>one</strong> source. For the two usual areas you therefore create <strong>two tabs</strong>:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Content</th><th>Source</th></tr></thead><tbody><tr><td><strong>My documents</strong></td><td>payslips, certificates, contract documents – visible to that person only</td><td>a view filtered on the signed-in user</td></tr><tr><td><strong>Company</strong></td><td>policies, handbook, templates – for everyone or an audience</td><td>a Grid or a view</td></tr></tbody></table><p>Both tabs use the same field schema. Whether a Grid holds personal or company documents is decided by the fields you maintain, nothing else.</p><p>The app keeps an <strong>offline copy</strong> of the list per tab on the device; the files themselves are loaded when opened and need a connection. All copies are deleted on logout.</p><h2 id="the-tabs-row" tabindex="-1">The tabs row <a class="header-anchor" href="#the-tabs-row" aria-label="Permalink to &quot;The tabs row&quot;">​</a></h2><p>In the <code>tabs</code> Grid of the team Space, add one row per area:</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Value</th></tr></thead><tbody><tr><td><code>title</code></td><td>for example &quot;My documents&quot; or &quot;Company&quot;</td></tr><tr><td><code>icon</code></td><td>single-color SVG</td></tr><tr><td><code>type</code></td><td><code>Documents</code></td></tr><tr><td><code>gridUri</code></td><td>link to the Grid or a view on it</td></tr><tr><td><code>uri</code></td><td>alternatively: the link of a shared view</td></tr></tbody></table><p>You need <strong>one</strong> of the two fields; if both are set, <code>gridUri</code> wins. If the documents live in a Space your staff has no access to, share a view there by link and enter the link in <code>uri</code>. No further field in the tabs Grid is needed. → <a href="/en/apptiveteams/tabs">Setting up tabs</a></p><h2 id="the-documents-grid" tabindex="-1">The documents Grid <a class="header-anchor" href="#the-documents-grid" aria-label="Permalink to &quot;The documents Grid&quot;">​</a></h2><p>Only <code>file</code> is required. Everything else appears when it is there. Field names are up to you, the <strong>Keys</strong> must match exactly. → <a href="/en/apptiveteams/team-space#keys-how-the-app-finds-its-grids">Assigning keys</a></p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>file</code></td><td>Files</td><td>yes</td><td>The file; the first one is used. Rows without a file don&#39;t appear</td></tr><tr><td><code>title</code></td><td>Text</td><td>no</td><td>Title. Without it the row is named &quot;document type period&quot;, otherwise after the file</td></tr><tr><td><code>recipient</code></td><td>User</td><td>for personal documents</td><td>The recipient; the view filters on it, see below</td></tr><tr><td><code>category</code></td><td>Single Select or Text</td><td>no</td><td>Category, for example &quot;Safety&quot;. With categories the list is grouped by them and filterable; otherwise it is grouped by year</td></tr><tr><td><code>type</code></td><td>Single Select or Text</td><td>no</td><td>Document type, for example &quot;Payslip&quot;</td></tr><tr><td><code>period</code></td><td>Date or Text</td><td>no</td><td>Period: as a date the first of the month (the app shows &quot;August 2026&quot;), as text for example &quot;2025&quot; for a yearly document</td></tr><tr><td><code>version</code></td><td>Text</td><td>no</td><td>Version, for example &quot;2.1&quot;</td></tr><tr><td><code>publishedAt</code></td><td>Date</td><td>no</td><td>Publication or provision</td></tr><tr><td><code>validFrom</code>, <code>validUntil</code></td><td>Date</td><td>no</td><td>Validity; after <code>validUntil</code> the app shows &quot;Expired&quot;</td></tr><tr><td><code>owner</code></td><td>Text or User</td><td>no</td><td>Responsible person or department</td></tr><tr><td><code>audience</code></td><td>Multi Select or Text</td><td>no</td><td>Audience – display only, see note</td></tr><tr><td><code>description</code></td><td>Text</td><td>no</td><td>Short description</td></tr><tr><td><code>acknowledge</code></td><td>Checkmark</td><td>no</td><td>Acknowledgement required</td></tr><tr><td><code>acknowledgeUntil</code></td><td>Date</td><td>no</td><td>Deadline for the acknowledgement</td></tr><tr><td><code>acknowledgeForm</code></td><td>Weblink</td><td>for self-service acknowledgements</td><td>Link of the form that creates an acknowledgement. <strong>Leave empty</strong> for assigned acknowledgements, see below</td></tr><tr><td><code>acknowledgements</code></td><td>Link or Multi Link</td><td>for acknowledgements</td><td>Points to the filtered view of the acknowledgements; the cell stays empty</td></tr><tr><td><code>active</code></td><td>Checkmark</td><td>no</td><td>Unchecked rows are hidden. Without the field all rows are visible</td></tr></tbody></table><p>A document without version, validity, description, owner, audience and acknowledgement – a payslip, say – opens its file directly when tapped. All others lead to a detail page.</p><div class="warning custom-block"><p class="custom-block-title"><code>audience</code> is not a permission</p><p>Who sees a document is decided by the view the tab points to – not by the value in <code>audience</code>. If policies should reach one site only, create a filtered view and a tab per site.</p></div><h2 id="personal-documents-the-view-filters" tabindex="-1">Personal documents: the view filters <a class="header-anchor" href="#personal-documents-the-view-filters" aria-label="Permalink to &quot;Personal documents: the view filters&quot;">​</a></h2><p>For &quot;My documents&quot; the tab does not point to the Grid but to a <strong>view</strong> with the filter <strong>recipient is the signed-in user</strong> (field <code>recipient</code>). The filter is evaluated on the server: every person gets only their own rows through the same address. Show <code>recipient</code> in the view.</p><div class="warning custom-block"><p class="custom-block-title">The app refuses an unfiltered view</p><p>If a view with the field <code>recipient</code> delivers rows of several people, the tab shows <strong>no</strong> documents but a notice about the missing filter. That guards against the most common mistake – a tab pointing to the Grid instead of the view. It does not replace the filter: without it the rows would still be readable through the API.</p></div><p><code>recipient</code> is a <strong>User</strong> field, not &quot;Created by&quot;: a payslip is created by HR or an import, but it is the recipient who may see it.</p><h2 id="acknowledgement" tabindex="-1">Acknowledgement <a class="header-anchor" href="#acknowledgement" aria-label="Permalink to &quot;Acknowledgement&quot;">​</a></h2><p>If a document has to be confirmed, set <code>acknowledge</code> and a deadline in <code>acknowledgeUntil</code>. The confirmation itself is a row in a second Grid, the <strong>acknowledgements Grid</strong>. There are two ways to get it there:</p><table tabindex="0"><thead><tr><th></th><th>Self service</th><th>Assignment</th></tr></thead><tbody><tr><td><strong>When the row is created</strong></td><td>when the person confirms</td><td>up front, per person and version – by hand or with a flow</td></tr><tr><td><strong>Open means</strong></td><td>there is no row yet</td><td>the row exists, the <code>done</code> checkmark is missing</td></tr><tr><td><strong>Who has not yet</strong></td><td>the difference to your staff list</td><td>in the Grid: all rows without <code>done</code></td></tr><tr><td><strong>Effort</strong></td><td>two columns, one form, no flow</td><td>plus three fields; you create the rows by hand for a few people, with a flow otherwise</td></tr><tr><td><strong>Fits</strong></td><td>handbook, policies, canteen menu</td><td>safety briefings, data protection – anything you must prove</td></tr></tbody></table><p><strong>The acknowledgements Grid itself decides which way applies:</strong> if it has a User field <code>recipient</code>, it assigns; otherwise it is self service. There is nothing to set in the app. Both ways can be mixed in the same documents Grid, see <a href="#both-side-by-side">Both side by side</a>.</p><h3 id="self-service-the-form-creates-the-row" tabindex="-1">Self service: the form creates the row <a class="header-anchor" href="#self-service-the-form-creates-the-row" aria-label="Permalink to &quot;Self service: the form creates the row&quot;">​</a></h3><p>The person confirms in the app, and that creates the row – &quot;Created by&quot; and &quot;Created at&quot; are set by ApptiveGrid; the app cannot create an acknowledgement on someone else&#39;s behalf.</p><h4 id="_1-the-acknowledgements-grid" tabindex="-1">1. The acknowledgements Grid <a class="header-anchor" href="#_1-the-acknowledgements-grid" aria-label="Permalink to &quot;1. The acknowledgements Grid&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>document</code></td><td>Link to the documents Grid</td><td>yes</td><td>The confirmed document</td></tr><tr><td><em>(any)</em></td><td>Created by</td><td>yes</td><td>Who confirmed; set automatically</td></tr><tr><td><code>version</code></td><td>Text</td><td>no</td><td>The confirmed version; the app fills it in</td></tr><tr><td><code>acknowledgedAt</code></td><td>Date and time</td><td>no</td><td>Moment of confirmation; the app fills it in. Without the field &quot;Created at&quot; is used</td></tr><tr><td><code>signature</code></td><td>Signature</td><td>no</td><td>If the form contains this field, the acknowledgement requires a signature</td></tr></tbody></table><h4 id="_2-the-view" tabindex="-1">2. The view <a class="header-anchor" href="#_2-the-view" aria-label="Permalink to &quot;2. The view&quot;">​</a></h4><p>Create a view on the acknowledgements Grid with the filter <strong>Created by is the signed-in user</strong> and show all fields. From this view the app reads what the person has already confirmed.</p><h4 id="_3-the-form" tabindex="-1">3. The form <a class="header-anchor" href="#_3-the-form" aria-label="Permalink to &quot;3. The form&quot;">​</a></h4><p>Create a form on the acknowledgements Grid with the field <code>document</code>, optionally <code>version</code> and <code>acknowledgedAt</code>. For a signature, add <code>signature</code>. Share the form with the restriction <strong>Any registered user</strong>, so that &quot;Created by&quot; is the person. → <a href="/en/formulare/formular-teilen">Sharing a form</a></p><h4 id="_4-two-columns-in-the-documents-grid" tabindex="-1">4. Two columns in the documents Grid <a class="header-anchor" href="#_4-two-columns-in-the-documents-grid" aria-label="Permalink to &quot;4. Two columns in the documents Grid&quot;">​</a></h4><ul><li><code>acknowledgeForm</code> (Weblink): the form link. It may be the same for all rows – the app fills in the document – or a prefilled link per row.</li><li><code>acknowledgements</code> (Link or Multi Link): points to the <strong>view</strong> from step 2, not to the Grid. The cell stays empty; the app only needs the address carried by the column. Show the column in the tab&#39;s view.</li></ul><p>No flow is needed.</p><div class="tip custom-block"><p class="custom-block-title">Signature</p><p>With the field <code>signature</code> in the form, the app shows the form with a signature pad instead of the confirm button. Without the field a single tap is enough. That way you decide per form – and thus per document – whether a signature is required. This holds for both ways.</p></div><h3 id="assignment-the-rows-are-there-first" tabindex="-1">Assignment: the rows are there first <a class="header-anchor" href="#assignment-the-rows-are-there-first" aria-label="Permalink to &quot;Assignment: the rows are there first&quot;">​</a></h3><p>If you must prove that everyone has read a document, turn the order around: the row exists before anyone has done anything, and it gets ticked off. Who creates it – you by hand or a flow – makes no difference to the app. The person sees the same card and the same button in the app; only what happens behind it differs.</p><h4 id="_1-three-more-fields-in-the-acknowledgements-grid" tabindex="-1">1. Three more fields in the acknowledgements Grid <a class="header-anchor" href="#_1-three-more-fields-in-the-acknowledgements-grid" aria-label="Permalink to &quot;1. Three more fields in the acknowledgements Grid&quot;">​</a></h4><p>In addition to <code>document</code> and the optional fields above:</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipient</code></td><td>User</td><td>yes</td><td>Whom the row was created for. <strong>This field switches assignment on</strong></td></tr><tr><td><code>done</code></td><td>Checkmark</td><td>yes</td><td>Done. The row is created unchecked, the app ticks it</td></tr><tr><td><code>editLink</code></td><td>Weblink</td><td>yes</td><td>The edit link of exactly this row – from the row&#39;s share dialog or from the flow</td></tr><tr><td><code>dueDate</code></td><td>Date</td><td>no</td><td>A deadline of this person&#39;s own. Takes precedence over the document&#39;s <code>acknowledgeUntil</code></td></tr></tbody></table><p>Fill <code>version</code> in every row. A row without a version counts for the document as a whole – version 2.2 would then be covered by the confirmation of 2.1.</p><p>A &quot;Created by&quot; field is not needed here; it does no harm either.</p><h4 id="_2-the-view-1" tabindex="-1">2. The view <a class="header-anchor" href="#_2-the-view-1" aria-label="Permalink to &quot;2. The view&quot;">​</a></h4><p>The view&#39;s filter is now <strong>recipient is the signed-in user</strong> (field <code>recipient</code>) instead of &quot;Created by&quot;. Show all fields, <code>editLink</code> included. The <code>acknowledgements</code> column in the documents Grid points to this view, just as with self service.</p><div class="warning custom-block"><p class="custom-block-title">The edit link opens exactly this row</p><p>Whoever has the link can edit the row – with no further check of who the person is. So it must reach only the person the row belongs to. That is exactly what the view&#39;s filter does: every person gets only their own rows and thus only their own links. Do not show <code>editLink</code> in any other shared view. → <a href="/en/formulare/eintraege-bearbeiten#security">Editing entries via form</a></p></div><h4 id="_3-the-form-1" tabindex="-1">3. The form <a class="header-anchor" href="#_3-the-form-1" aria-label="Permalink to &quot;3. The form&quot;">​</a></h4><p>A form on the acknowledgements Grid with the field <code>done</code>, optionally <code>acknowledgedAt</code> and <code>signature</code>. It does not need <code>document</code> – that is already in the row. This is the form the edit link opens; the app ticks <code>done</code> and submits. With <code>signature</code> it shows the form, the checkmark already set.</p><h4 id="_4-creating-the-rows-by-hand-or-with-a-flow" tabindex="-1">4. Creating the rows: by hand or with a flow <a class="header-anchor" href="#_4-creating-the-rows-by-hand-or-with-a-flow" aria-label="Permalink to &quot;4. Creating the rows: by hand or with a flow&quot;">​</a></h4><p>One row per person and version: <code>recipient</code>, <code>document</code>, <code>version</code>, <code>dueDate</code> if needed; <code>done</code> stays empty. Then the row&#39;s edit link goes into <code>editLink</code>.</p><p><strong>By hand</strong> is enough for a small team or a single briefing: create the rows, generate the link with the form from step 3 via the share dialog <strong>Share for editing</strong> of each row, and enter it in <code>editLink</code>. → <a href="/en/formulare/eintraege-bearbeiten#sharing-an-entry-for-editing">Sharing an entry for editing</a></p><p><strong>With a flow</strong> when there are many people or new versions come regularly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: Entry was changed   (documents Grid, e.g. \`publishedAt\` set)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Load all entries             → your staff, filtered to the audience if needed</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                     → for each person:</span></span>
<span class="line"><span>   ├ Create entry            → acknowledgements Grid: recipient, document, version, dueDate; done empty</span></span>
<span class="line"><span>   ├ Prefilled form link     → the form from step 3 for the new row</span></span>
<span class="line"><span>   └ Update entry            → write the link into editLink</span></span></code></pre></div><p>Until a row is created and its link written, the detail page in the app says &quot;The acknowledgement is being prepared&quot;. For a new version you create new rows – or the flow runs again; the old ones no longer match the new version, and the document is open again.</p><p>→ <a href="/en/flows/aktionen#create-entry">Actions</a> · <a href="/en/flows/router-und-parallel">Parallel</a> · <a href="/en/flows/aktionen#prefilled-form-link">Prefilled form link</a> · <a href="/en/flows/trigger#entry-was-changed">Triggers</a></p><h4 id="_5-clear-acknowledgeform" tabindex="-1">5. Clear <code>acknowledgeForm</code> <a class="header-anchor" href="#_5-clear-acknowledgeform" aria-label="Permalink to &quot;5. Clear \`acknowledgeForm\`&quot;">​</a></h4><p>Leave <code>acknowledgeForm</code> empty for the documents that are assigned. A document that still carries the link stays self service – see the next section.</p><h3 id="both-side-by-side" tabindex="-1">Both side by side <a class="header-anchor" href="#both-side-by-side" aria-label="Permalink to &quot;Both side by side&quot;">​</a></h3><p>The choice is made <strong>per document</strong>, not per Grid: an assignment concerns one document, not the next. In a documents Grid whose acknowledgements Grid assigns, each row works like this:</p><table tabindex="0"><thead><tr><th>Situation</th><th>What the app does</th></tr></thead><tbody><tr><td>Assigned row with edit link</td><td>confirm button; this row gets ticked off</td></tr><tr><td>Assigned row, link still missing</td><td>&quot;The acknowledgement is being prepared&quot; – <code>editLink</code> is still empty</td></tr><tr><td>No row, document has <code>acknowledgeForm</code></td><td>self service as above; the new row is created with <code>done</code> set</td></tr><tr><td>No row, no <code>acknowledgeForm</code></td><td>&quot;The acknowledgement is being prepared&quot;</td></tr></tbody></table><p>That way you assign the safety briefings and let people tick off the canteen menu themselves – in the same Grid, with the same acknowledgements Grid.</p><div class="warning custom-block"><p class="custom-block-title">Clear <code>acknowledgeForm</code> when switching</p><p>If you switch from self service to assignment, <code>acknowledgeForm</code> is still set in every row. For those documents it stays self service although rows already exist – and on confirming, the person creates a second row next to the assigned one. The app cannot tell the two apart; it only names such documents in the developer log. Clear the column wherever you assign.</p></div><h2 id="how-the-app-works" tabindex="-1">How the app works <a class="header-anchor" href="#how-the-app-works" aria-label="Permalink to &quot;How the app works&quot;">​</a></h2><ul><li>On opening the tab, the app loads the list and stores it as an offline copy per tab. Without a connection it shows the last loaded state; the files need a connection.</li><li>With categories the list is grouped by them, alphabetically. Otherwise it is grouped by year, newest on top – for payslips and certificates.</li><li>Above the list a notice names the open acknowledgements with the nearest deadlines; overdue ones are marked red.</li><li>A new version of a document counts as &quot;new&quot; again and has to be confirmed again if the acknowledgement names a version.</li><li>With assigned acknowledgements the app shows each person only their own rows. Who has not confirmed yet is visible in the acknowledgements Grid, not in the app.</li><li>On logout the copies of all teams are deleted from the device.</li></ul><h2 id="when-something-is-missing" tabindex="-1">When something is missing <a class="header-anchor" href="#when-something-is-missing" aria-label="Permalink to &quot;When something is missing&quot;">​</a></h2><p>The app names missing field Keys right in the tab, together with the fields the source actually delivers.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td>No tab in the app</td><td>Tabs row incomplete: <code>type</code>, <code>gridUri</code>/<code>uri</code> or the icon is missing</td></tr><tr><td>&quot;Missing field keys: file&quot;</td><td>The files field has no Key <code>file</code></td></tr><tr><td>Notice &quot;not filtered to the logged in user&quot;</td><td>The tab points to the Grid of personal documents instead of the filtered view</td></tr><tr><td>No confirm button, &quot;No acknowledgement is set up&quot;</td><td>Self service: <code>acknowledgeForm</code> is empty</td></tr><tr><td>&quot;The acknowledgement is being prepared&quot; does not go away</td><td>Assignment: there is no row for this person and version, or <code>editLink</code> is empty – with a flow, check its run history</td></tr><tr><td>Everything counts as confirmed right away</td><td>Assignment without the <code>done</code> checkmark – without the field every created row is a confirmation. The app reports the missing Keys <code>done</code>/<code>editLink</code> in the status line</td></tr><tr><td>Confirmed, but open again after refreshing</td><td><code>acknowledgements</code> is missing, has a different Key, or points to a different Grid than the form</td></tr><tr><td>Two rows for the same document after confirming</td><td>Assignment, but <code>acknowledgeForm</code> is still set on the document – clear the column</td></tr><tr><td>Status line &quot;Acknowledgements could not be loaded&quot;</td><td>The acknowledgements view is unreachable, or it lacks <code>document</code>, &quot;Created by&quot;, or – for assignment – <code>done</code>/<code>editLink</code></td></tr><tr><td>No deadline in the notice</td><td>The date field has no Key <code>acknowledgeUntil</code></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/tabs">Setting up tabs</a></li><li><a href="/en/ansichten/ansicht-teilen">Sharing a view</a></li><li><a href="/en/formulare/formular-teilen">Sharing a form</a></li><li><a href="/en/formulare/eintraege-bearbeiten">Editing entries via form</a></li><li><a href="/en/flows/router-und-parallel">Router and Parallel</a></li><li><a href="/en/apptiveteams/fehlerbehebung">Tips and troubleshooting</a></li></ul>`,68)])])}const u=t(a,[["render",i]]);export{m as __pageData,u as default};
